PW=$(cat /root/.mariadb_root_pw)
mysql -u root -p"$PW" <<SQL
CREATE DATABASE IF NOT EXISTS appdata;
CREATE TABLE IF NOT EXISTS appdata.orders (id INT PRIMARY KEY AUTO_INCREMENT, note VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO appdata.orders (note) VALUES ('seed-1'),('seed-2'),('seed-3');
CREATE USER IF NOT EXISTS 'appuser'@'%' IDENTIFIED BY [REDACTED];
GRANT ALL PRIVILEGES ON appdata.* TO 'appuser'@'%';
FLUSH PRIVILEGES;
SQL
mysql -u root -p"$PW" -e "SELECT COUNT(*) FROM appdata.orders;"

